head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40300";
scwin.isurCdTitle = '';

// [A] 초기 목록 미해결 — jldfil40300: 진입 키 findid 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40300.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_corpUsrTpCd_onchange
 * @description slc_corpUsrTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_corpUsrTpCd_onchange = function(e){
    try {
        scwin.chgCorpUsrTpCd()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40300.slc_corpUsrTpCd_onchange' }); }
};

/**
 * @method
 * @name slc_selEmail_onchange
 * @description slc_selEmail 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_onchange = function(e){
    try {
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selEmail"), $c.util.getComponent('ipt_apctEmail2'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40300.slc_selEmail_onchange' }); }
};

/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40300.btn_Confirm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/register/findId.do",
        ref: "dma_ConfirmReq",
        target: "dlt_codeVOList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    const frm = (document.findIdForm || { elements: [] });
    if (await scwin.checkRequired($c.util.getComponent("slc_corpUsrTpCd"), "사용자1")) {  // as-is alt="사용자1" + checkRequired(DOM)
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_isurCd'), scwin.isurCdTitle.replace('\n', ' '))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length !== 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "신청자"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_apctEmail1')) || await scwin.checkRequired($c.util.getComponent('ipt_apctEmail2'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('apctEmail', $c.str.trim($c.util.getComponent('ipt_apctEmail1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_apctEmail2').getValue()));
    if (!$c.str.isEmail($c.util.getComponent('dma_ConfirmReq').get('apctEmail'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', 'registerIDIssueInformation');
    frm.action = 'findId.do';
    const nr = await scwin.tx_fn_Confirm();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil40301/jldfil40301.xml", { "method": 'registerIDIssueInformation' });
    }
};

/**
 * @method
 * @name chgCorpUsrTpCd
 * @description chg Corp Usr Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.chgCorpUsrTpCd = function () {
    const frm = (document.findIdForm || { elements: [] });
    const corpUsrTpCd = $c.util.getComponent('slc_corpUsrTpCd').getValue();
    let inputDisplayVal = '';
    if (corpUsrTpCd === '14') {
        scwin.isurCdTitle = '대상회사코드(5자리)';
        inputDisplayVal = 'inline';
    } else {
        if (corpUsrTpCd === '22') {
            scwin.isurCdTitle = '회원고유코드';
            inputDisplayVal = 'none';
        } else {
            scwin.isurCdTitle = '회사코드(5자리)';
            if (corpUsrTpCd === '11' || corpUsrTpCd === '12' || corpUsrTpCd === '21') {
                inputDisplayVal = 'none';
            } else {
                if (corpUsrTpCd === '15' || corpUsrTpCd === '23') {
                    inputDisplayVal = 'inline';
                } else {
                    inputDisplayVal = 'none';
                }
            }
        }
    }
    ($c.util.getComponent('txt_isurCdTitle') && $c.util.getComponent('txt_isurCdTitle').setValue) ? $c.util.getComponent('txt_isurCdTitle').setValue(scwin.isurCdTitle) : (($c.util.getComponent('txt_isurCdTitle') && $c.util.getComponent('txt_isurCdTitle').setText) ? $c.util.getComponent('txt_isurCdTitle').setText(scwin.isurCdTitle) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'txt_isurCdTitle'), void (scwin.isurCdTitle)));
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
